window.REC_META = {"repo": "espnow-demos", "subtitle": "Un bridge, nueve nodos y una GUI para ver la red en vivo", "description": "Recorrido por espnow-demos: una red ESP-NOW autodescubierta donde un NodeMCU bridge interroga a nueve nodos sensores y publica las respuestas por serial. El video sigue el protocolo de 13 bytes, el aprendizaje de MAC por broadcast, el nodo de vibración y la GUI PyQt6 que convierte el log en tarjetas.", "repo_url": "https://github.com/jmadasme/espnow-demos", "page_url": "https://jmadasme.github.io/espnow-demos/", "poster_text": "Recorrido por espnow-demos: una red ESP-NOW autodescubierta donde un NodeMCU bridge interroga a nueve nodos sensores y publica las respuestas por serial. El video sigue el protocolo de 13 bytes, el aprendizaje de MAC por broadcast, el nodo de vibración y la GUI PyQt6 que convierte el log en tarjetas.", "commands": ["cd versions/espNowDemo", "arduino-cli compile --fqbn esp8266:esp8266:nodemcuv2 firmware_bridge", "arduino-cli upload -p /dev/ttyUSB0 --fqbn esp8266:esp8266:nodemcuv2 firmware_bridge", "pip install PyQt6 pyserial", "python3 espnow_gui.py"], "chapters": [{"time": "0:06", "label": "EL PROBLEMA", "title": "Nueve sensores, un solo cable"}, {"time": "0:20", "label": "ARQUITECTURA", "title": "Una tabla con ocho MAC en cero"}, {"time": "0:34", "label": "EL NÚCLEO", "title": "Un mensaje de trece bytes"}, {"time": "0:48", "label": "EL NÚCLEO", "title": "La ISR solo copia y avisa"}, {"time": "1:02", "label": "AUTODESCUBRIMIENTO", "title": "Broadcast hasta aprender la MAC"}, {"time": "1:17", "label": "APRENDIZAJE", "title": "La respuesta enseña quién es"}, {"time": "1:29", "label": "ORQUESTACIÓN", "title": "Poll cada tres segundos, timeout de dos"}, {"time": "1:46", "label": "HARDWARE", "title": "Nodo 8: cincuenta muestras de vibración"}, {"time": "2:01", "label": "RESPUESTA", "title": "Del ADC a la trama de dieciséis bytes"}, {"time": "2:15", "label": "LA GUI", "title": "Un hilo que solo lee líneas"}, {"time": "2:28", "label": "LA GUI", "title": "Parsear el bloque, pintar la tarjeta"}, {"time": "2:43", "label": "CÓMO EJECUTARLO", "title": "Compilar, flashear, abrir la GUI"}], "width": 104, "height": 34, "duration": 186.72, "title": "ESP-NOW sin infraestructura"};
